function classify(root) {
  let full = true, complete = true;
  let gap = false;                    // passed an empty child slot yet?
  let count = 0;
  const queue = [root];
  while (queue.length > 0) {
    const node = queue.shift();
    count++;
    if ((node.left === null) !== (node.right === null)) full = false;   // exactly one child
    for (const child of [node.left, node.right]) {
      if (child === null) {
        gap = true;
      } else {
        if (gap) complete = false;    // a node after a gap
        queue.push(child);
      }
    }
  }
  const perfect = complete && ((count + 1) & count) === 0;   // count is 2^k - 1
  return [full, complete, perfect];
}

from collections import deque

def classify(root):
    full = complete = True
    gap = False                         # passed an empty child slot yet?
    count = 0
    queue = deque([root])
    while queue:
        node = queue.popleft()
        count += 1
        if (node.left is None) != (node.right is None):
            full = False                # exactly one child
        for child in (node.left, node.right):
            if child is None:
                gap = True
            else:
                if gap:
                    complete = False    # a node after a gap
                queue.append(child)
    perfect = complete and (count + 1) & count == 0   # count is 2^k - 1
    return [full, complete, perfect]

List<Boolean> classify(TreeNode root) {
    boolean full = true, complete = true;
    boolean gap = false;                    // passed an empty child slot yet?
    int count = 0;
    Queue<TreeNode> queue = new ArrayDeque<>();
    queue.offer(root);
    while (!queue.isEmpty()) {
        TreeNode node = queue.poll();
        count++;
        if ((node.left == null) != (node.right == null)) full = false;   // exactly one child
        for (TreeNode child : new TreeNode[]{node.left, node.right}) {
            if (child == null) {
                gap = true;
            } else {
                if (gap) complete = false;  // a node after a gap
                queue.offer(child);
            }
        }
    }
    boolean perfect = complete && ((count + 1) & count) == 0;   // count is 2^k - 1
    return List.of(full, complete, perfect);
}

vector<bool> classify(TreeNode* root) {
    bool full = true, complete = true;
    bool gap = false;                       // passed an empty child slot yet?
    int count = 0;
    queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        TreeNode* node = q.front();
        q.pop();
        count++;
        if ((node->left == nullptr) != (node->right == nullptr)) full = false;   // exactly one child
        for (TreeNode* child : {node->left, node->right}) {
            if (child == nullptr) {
                gap = true;
            } else {
                if (gap) complete = false;  // a node after a gap
                q.push(child);
            }
        }
    }
    bool perfect = complete && ((count + 1) & count) == 0;   // count is 2^k - 1
    return {full, complete, perfect};
}
